tool_input.command:
node --test test/ 2>&1 | tail -12; echo ---; grep -rn "handle\|api.js" src/; echo ---; node --input-type=module -e "
import { handle } from './src/api.js';
import { tick } from './src/scheduler.js';
for (const [tz, label] of [[330,'IST'],[-300,'EST']]) {
  const { body } = handle({ method:'POST', path:'/reminders', body:{ userId:label, text:'call mum', at:'2026-03-01T09:00', tzOffsetMin: tz } });
  console.log(label, 'due_ms =', new Date(body.due_ms).toISOString());
}
for (const now of ['2026-02-28T22:00:00Z','2026-03-01T03:30:00Z','2026-03-01T14:00:00Z','2026-03-01T19:00:00Z']) {
  const lines = [];
  await tick(Date.parse(now), { formatter:'legacy', out: l => lines.push(l) });
  console.log('tick', now, '->', lines);
}
"
